discovery.code:
// the attacker decodes, edits and re-encodes the payload
payload: {"sub":"alice","role":"user"}  ->  {"sub":"alice","role":"admin"}
// header and signature segments are left exactly as they were
GET /admin/reports   Authorization: Bearer <edited token>

Header header = decodeHeader(token);       // read out of the token itself
String alg = header.get("alg");            // e.g. "HS256"
if (verifySignature(token, alg, key)) {
    return trustClaims(token);
}

// service sitting behind the API gateway
String user = request.getHeader("X-Authenticated-User");  // set by the gateway
if (user != null) {
    return actAs(user);
}

// browser app: JWT in localStorage, exp = 60 minutes, no deny-list
09:00  alice logs in, auth signs {"sub":"alice","role":"admin","exp":"10:00"}
09:10  support bans alice and deletes her row
09:11  alice's browser calls GET /admin/reports with the same token
       the service checks the signature, exp, iss and aud

practice.code:
Header header = decodeHeader(token);
Claims claims = Jwt.parser()
        .algorithm(header.alg())      // algorithm taken from the token
        .key(publicKey)
        .requireExpiry()
        .parse(token);
return claims.subject();

// token: {"iss":"auth","aud":"reports","scope":"read","exp":"+60s"}
// payments verifies it:
//   signature ok (issuer public key)
//   exp ok, iss = auth ok
